["events"] = "CLEU:UNIT_DIED PLAYER_DEAD PLAYER_REGEN_ENABLED UNIT_THREAT_LIST_UPDATE SCENARIO_POI_UPDATE CHALLENGE_MODE_START CHALLENGE_MODE_COMPLETED SCENARIO_CRITERIA_UPDATE",
["custom"] = "function(s, e, ...)\n    aura_env.update = false\n    if e == \"OPTIONS\" then\n        aura_env.finish = false        \n        local progress, mobCount, currentMC, totalMC = aura_env.GetProgress()\n        local total = 100\n        aura_env.total = totalMC or 0\n        if progress >= 100 then\n            local cmap = aura_env.cmap\n            local level = aura_env.level \n            local max = select(3, C_Scenario.GetStepInfo())\n            local cur = C_ScenarioInfo.GetCriteriaInfo(max) and select(2, GetWorldElapsedTime(1))-C_ScenarioInfo.GetCriteriaInfo(max).elapsed or 0\n            local haspb = aura_env.config.splits and aura_env.saved and aura_env.saved[cmap] and aura_env.saved[cmap][level] and aura_env.saved[cmap][level][0]\n            if haspb then\n                local split = cur-aura_env.saved[cmap][level][0]\n                local prefix = cur <= split and \"|cFF00FF00 \" or \"|cFFFF0000 +\"\n                aura_env.finish = aura_env.formattime(cur, aura_env.color)..prefix..aura_env.formattime(split, aura_env.color)\n            else\n                aura_env.finish = aura_env.formattime(cur, aura_env.color)\n            end\n        end\n        s[\"\"] = {\n            progressType = \"static\",\n            value = progress,\n            total = total,\n            currentMC = currentMC,\n            totalMC = totalMC,\n            mobCount = mobCount,\n            pull = {},\n            pullText = \"\",\n            mcpullText = \"\",\n            pullCompare = 1,\n            mcpullCompare = 1,\n            mcCompare = totalMC/100*total - currentMC,\n            leftCompare = total - progress,\n            current = string.format(\"%.2f%%\", progress),\n            left = string.format(\"%.2f%%\", total - progress),\n            show = true,\n            additionalProgress = {\n                { \n                    direction = \"forward\",\n                    width = 0,\n                    offset = 0,\n                }\n            },\n            changed = true,\n        }\n    elseif e == \"CHALLENGE_MODE_COMPLETED\" then\n        \n        local finish = select(3, C_ChallengeMode.GetCompletionInfo())\n        local cmap = aura_env.cmap\n        local level = aura_env.level \n        if cmap and level then\n            if not aura_env.saved then aura_env.saved = {} end\n            if not aura_env.saved[cmap] then aura_env.saved[cmap] = {} end\n            if not aura_env.saved[cmap][level] then aura_env.saved[cmap][level] = {} end\n            \n            if not aura_env.saved[cmap][level][\"finish\"] or finish < aura_env.saved[cmap][level][\"finish\"] then\n                aura_env.saved[cmap][level][\"finish\"] = finish\n                aura_env.saved[cmap][level][0] = aura_env.finishtime\n            end\n        end\n        s[\"\"].value = 100\n        s[\"\"].total = 100\n        s[\"\"].changed = true\n        return true\n    elseif e == \"SCENARIO_POI_UPDATE\" or e == \"CHALLENGE_MODE_START\" or e == \"SCENARIO_CRITERIA_UPDATE\" or e == \"STATUS\" then\n        local time = select(3, C_ChallengeMode.GetCompletionInfo())\n        if e == \"CHALLENGE_MODE_START\" then\n            \n            aura_env.finish = false\n            aura_env.done = false\n            aura_env.update = true\n            aura_env.cmap = nil\n            local level, affixes = C_ChallengeMode.GetActiveKeystoneInfo()\n            aura_env.cmap = C_ChallengeMode.GetActiveChallengeMapID()\n            aura_env.level = level\n        end\n        if time == 0 and not aura_env.cmap then\n            local level, affixes = C_ChallengeMode.GetActiveKeystoneInfo()\n            aura_env.cmap = C_ChallengeMode.GetActiveChallengeMapID()\n            aura_env.level = level\n        end\n        local progress, mobCount, currentMC, totalMC = aura_env.GetProgress()\n        totalMC = totalMC or 0\n        aura_env.total = totalMC\n        if time ~= 0 then \n            progress = 100 \n            currentMC = totalMC\n            mobCount = currentMC..\"/\"..totalMC\n        end\n        if not aura_env.done then\n            progress = progress or 0\n        end\n        if progress then\n            currentMC = currentMC or totalMC\n            mobCount = mobCount or 0\n            local total = 100\n            \n            aura_env.total = aura_env.total or 0\n            \n            if progress >= 100 and not aura_env.done then\n                \n                local max = select(3, C_Scenario.GetStepInfo())\n                local defeat = C_ScenarioInfo.GetCriteriaInfo(max) and C_ScenarioInfo.GetCriteriaInfo(max).elapsed or 0\n                local cur = select(2, GetWorldElapsedTime(1)) - defeat\n                local cmap = aura_env.cmap\n                local level = aura_env.level \n                local haspb = aura_env.config.splits and aura_env.saved and aura_env.saved[cmap] and aura_env.saved[cmap][level] and aura_env.saved[cmap][level][0]\n                if haspb then                \n                    local pb = aura_env.saved[cmap][level][0]\n                    if cur == pb then\n                        aura_env.finish = aura_env.formattime(cur, aura_env.color)..\" |cFFFFEA00 +-0\"\n                    else\n                        local prefix = cur <= pb and \" -\" or \" +\"\n                        local color = cur <= pb and \"|cFF00FF00\" or \"|cFFFF0000\"\n                        local diff = cur-pb\n                        if diff < 0 then diff = diff*-1 end\n                        aura_env.finish = \"[\"..aura_env.formattime(cur, aura_env.color)..\"]\"..color..prefix..aura_env.formattime(diff, color)\n                    end\n                else\n                    aura_env.finish = \"[\"..aura_env.formattime(cur, aura_env.color)..\"]\"\n                end\n                aura_env.finishtime = cur\n            end\n            if (e == \"STATUS\" or e == \"SCENARIO_CRITERIA_UPDATE\" or e == \"SCENARIO_POI_UPDATE\") and progress >= 100 and s[\"\"] and not aura_env.done then\n                aura_env.done = true\n                aura_env.update = true\n                \n                s[\"\"].value = 100\n                s[\"\"].total = 100\n                s[\"\"].mobCount = mobCount\n                s[\"\"].currentMC = s[\"\"].totalMC\n                s[\"\"].mcCompare = s[\"\"].totalMC >= s[\"\"].currentMC and s[\"\"].totalMC - s[\"\"].currentMC or 0\n                s[\"\"].leftCompare = total - progress\n                s[\"\"].current = string.format(\"%.2f%%\", progress)\n                s[\"\"].left = string.format(\"%.2f%%\", total - progress)\n                s[\"\"].additionalProgress = {\n                    { \n                        direction = \"forward\",\n                        width = 0,\n                        offset = 0,\n                    }\n                }\n                s[\"\"].changed = true\n                \n            elseif not s[\"\"] then\n                aura_env.update = true\n                s[\"\"] = {\n                    progressType = \"static\",\n                    value = progress,\n                    total = total, \n                    currentMC = currentMC,\n                    totalMC = totalMC,\n                    mobCount = mobCount,\n                    pull = {},\n                    pullText = \"\",\n                    mcpullText = \"\",\n                    pullCompare = 1,\n                    mcpullCompare = 1,\n                    mcCompare = totalMC >= currentMC and totalMC - currentMC or 0,\n                    leftCompare = total - progress,\n                    current = string.format(\"%.2f%%\", progress),\n                    left = string.format(\"%.2f%%\", total - progress),\n                    show = true,\n                    additionalProgress = {\n                        { \n                            direction = \"forward\",\n                            width = 0,\n                            offset = 0,\n                        }\n                    },\n                    changed = true,\n                }\n                aura_env.total = totalMC\n            elseif progress < 100 and s[\"\"] then\n                aura_env.update = true\n                s[\"\"].value = progress\n                s[\"\"].total = total\n                s[\"\"].mobCount = mobCount\n                s[\"\"].currentMC = currentMC\n                s[\"\"].totalMC = totalMC\n                s[\"\"].mcCompare = totalMC >= currentMC and totalMC - currentMC or 0\n                s[\"\"].leftCompare = total - progress\n                s[\"\"].current = string.format(\"%.2f%%\", progress)\n                s[\"\"].left = string.format(\"%.2f%%\", total - progress)\n                s[\"\"].changed = true\n                \n                \n                \n                local rawValue, percentValue = 0, 0\n                for _, value in pairs(s[\"\"].pull) do \n                    if value ~= \"DEAD\" then\n                        rawValue = rawValue + value[1]\n                        percentValue = percentValue + value[2]\n                    end\n                end\n                \n                local rawtext, text = \"\", \"\"\n                if percentValue > 0 or rawValue > 0 then\n                    rawtext = rawValue\n                    text = percentValue\n                end\n                \n                s[\"\"].mcpullCompare = s[\"\"].mcCompare - rawValue\n                s[\"\"].mcpullText = rawtext\n                \n                s[\"\"].pullCompare = s[\"\"].leftCompare - percentValue\n                s[\"\"].pullText = text ~= \"\" and string.format(\"%.2f%%\", text) or text\n                \n                s[\"\"].additionalProgress = {\n                    { \n                        direction = \"forward\",\n                        width = (percentValue+s[\"\"].value < 100 and percentValue) or 100,\n                        offset = 0,\n                    }\n                }\n            end\n        end\n        \n    elseif e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, se, _, _, _, _, _, destGUID = ...\n        if se == \"UNIT_DIED\" and destGUID then\n            local npcID = select(6, strsplit(\"-\", destGUID))\n            if s[\"\"] and s[\"\"].pull[destGUID] then\n                aura_env.update = true           \n                s[\"\"].pull[destGUID] = \"DEAD\"\n            end\n        end\n    end\n    if aura_env.pullcount and aura_env.MDT and s[\"\"] then\n        if e == \"UNIT_THREAT_LIST_UPDATE\" and InCombatLockdown() then\n            local unit = ...\n            if unit and UnitExists(unit) then\n                local guid = UnitGUID(unit)\n                local id = select(6, strsplit(\"-\", guid))\n                if guid and not s[\"\"].pull[guid] then\n                    local npc_id = select(6, strsplit(\"-\", guid))\n                    if npc_id then                        \n                        local value = aura_env.MDT:GetEnemyForces(tonumber(npc_id))   \n                        if value and value ~= 0 then\n                            s[\"\"].pull[guid] = {value, (value / (aura_env.total)) * 100}\n                            aura_env.update = true\n                        end\n                    end\n                end            \n            end\n            \n        elseif (e == \"PLAYER_REGEN_ENABLED\" or e == \"PLAYER_DEAD\") and s[\"\"].pull then\n            for k, _ in pairs(s[\"\"].pull) do\n                s[\"\"].pull[k] = nil\n            end\n            aura_env.update = true\n        end\n        \n        if aura_env.update then\n            local rawValue, percentValue = 0, 0\n            for _, value in pairs(s[\"\"].pull) do \n                if value ~= \"DEAD\" then\n                    rawValue = rawValue + value[1]\n                    percentValue = percentValue + value[2]\n                end\n            end\n            \n            local rawtext, text = \"\", \"\"\n            if percentValue > 0 or rawValue > 0 then\n                rawtext = rawValue\n                text = percentValue\n            end\n            \n            \n            if aura_env.countD == 2 then\n                rawtext = (s[\"\"].currentMC and rawtext ~= \"\" and tonumber(rawtext)+s[\"\"].currentMC) or \"\"\n                text = rawtext ~= \"\" and (rawtext/aura_env.total)*100 or \"\"\n            end\n            \n            s[\"\"].mcpullCompare = s[\"\"].mcCompare - rawValue\n            s[\"\"].mcpullText = rawtext\n            \n            \n            s[\"\"].pullCompare = s[\"\"].leftCompare - percentValue\n            s[\"\"].pullText = text ~= \"\" and string.format(\"%.2f%%\", text) or text\n            s[\"\"].additionalProgress = {\n                { \n                    direction = \"forward\",\n                    width = (percentValue+s[\"\"].value < 100 and percentValue) or 100,\n                    offset = 0,\n                }\n            }\n            s[\"\"].changed = true\n        end\n    end\n    return aura_env.update\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
