["init"] = {
["do_custom"] = true,
["custom"] = "function aura_env.getGatewayID()\n    local id\n    for i=1,200 do\n        id = select(2,GetActionInfo(i))\n        if id == 188152 then --Gateway Control Shard\n            aura_env.actionId = i\n            break\n        end\n    end\nend\n\naura_env.getGatewayID()",
