["custom"] = "function(event)\n    if event == \"ACTIONBAR_UPDATE_USABLE\" then\n        if IsUsableAction(aura_env.actionId) then\n            return true\n        end\n    elseif event == \"ACTIONBAR_SLOT_CHANGED\" then\n        aura_env.getGatewayID()\n    end\nend",
