["Booty Fixate (nameplate)"] = {
["wagoID"] = "Jvpud9Ahy",
["authorOptions"] = {
},
["preferToUpdate"] = false,
["yOffset"] = 10,
["anchorPoint"] = "TOP",
["url"] = "https://wago.io/LiquidUndermine/4",
["actions"] = {
["start"] = {
