["customSort"] = "function(a, b)\n    local stateA = a.region.state\n    local stateB = b.region.state\n    \n    local affectedA = (stateA.stacks or 0) > 0\n    local affectedB = (stateB.stacks or 0) > 0\n    \n    local expirationTimeA = stateA.expirationTime or 0\n    local expirationTimeB = stateB.expirationTime or 0\n    \n    local roleA = stateA.role or \"NONE\"\n    local roleB = stateB.role or \"NONE\"\n    \n    local guidA = stateA.GUID or \"\"\n    local guidB = stateB.GUID or \"\"\n    \n    if affectedA ~= affectedB then\n        return affectedA\n    elseif expirationTimeA ~= expirationTimeB then\n        return expirationTimeA > expirationTimeB\n    elseif roleA ~= roleB then\n        return roleA < roleB\n    else\n        return guidA < guidB\n    end\nend",
