},
["custom"] = "function(allstates, event, _, triggerStates)\n    if event == \"OPTIONS\" then\n        allstates[1] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = math.random(1000000, 100000000),\n            total = 100000000,\n            skipPosition = true\n        }\n    elseif event == \"TRIGGER\" then\n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        local triggerState = triggerStates and triggerStates[\"\"]\n        \n        if not (triggerState and triggerState.show) then\n            aura_env.maxAbsorb = nil\n            \n            return true\n        end\n        \n        local absorb = triggerState.tooltip1 or 0\n        \n        if not aura_env.maxAbsorb or absorb > aura_env.maxAbsorb then\n            aura_env.maxAbsorb = absorb\n        end\n        \n        allstates[1] = {\n            show = true,\n            changed = true,\n            progressType = \"static\",\n            value = absorb,\n            total = aura_env.maxAbsorb,\n            index = 1,\n            skipPosition = true,\n        }\n        \n        return true\n    end\nend",
["events"] = "TRIGGER:2",
["check"] = "event",
["unit"] = "player",
