["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 4,\n            expirationTime = GetTime() + 4,\n            autoHide = true\n        }\n    elseif event == \"CHAT_MSG_MONSTER_EMOTE\" then\n        local _, playerName, _, _, targetName = ...\n        \n        if not playerName then return end\n        if not targetName then return end\n        \n        local spellInfo = C_Spell.GetSpellInfo(464865) -- Discarded Doomsplosive\n        local localizedName = spellInfo.name\n        \n        if playerName == WeakAuras.me and (targetName:match(localizedName) or targetName:match(\"Discarded Doomsplosive\")) then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 4,\n                expirationTime = GetTime() + 4,\n                autoHide = true\n            }\n            \n            return true\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, sourceGUID, _, _, _, _, _, _, _, _, _, _, extraSpellID = ...\n        \n        if subEvent == \"SPELL_INTERRUPT\" and sourceGUID == WeakAuras.myGUID and extraSpellID == 1219384 then -- Scrap Rockets\n            local state = allstates[\"\"]\n            \n            if state then\n                state.show = false\n                state.changed = true\n                \n                return true\n            end\n        end\n    end\nend",
