["url"] = "https://wago.io/M+Timer/133",
["actions"] = {
["start"] = {
["custom"] = "if aura_env.config[\"hideobj\"] then\n    aura_env.frame:Hide()\nend\n\n\n\n",
["do_custom"] = true,
["sound"] = "Interface\\Addons\\WeakAuras\\PowerAurasMedia\\Sounds\\chant2.ogg",
["do_sound"] = false,
},
["finish"] = {
["hide_all_glows"] = false,
["custom"] = "if aura_env.config[\"hideobj\"] then\n    aura_env.frame:Show()\nend",
["do_custom"] = true,
},
["init"] = {
["custom"] = "aura_env.keyslot = aura_env.config[\"KeySlot\"]\n\naura_env.keyID = {\n    [138019] = true, -- Legion\n    [158923] = true, -- Battle for Azeroth\n    [180653] = true, -- Shadowlands\n    [186159] = true, -- Dragonflight\n    [187786] = true, -- Timewalking\n    [151086] = true, -- Tournament Realm?\n    \n}\naura_env.gossips = {}\nfor _, v in pairs(aura_env.config.gossip) do\n    aura_env.gossips[v.npcid] = {enabled = v.enabled, number = v.gossipnum}\nend\n\n\n\n\naura_env.popup = function()\n    for index = 1, STATICPOPUP_NUMDIALOGS do\n        local frame = _G[\"StaticPopup\"..index]\n        if frame and frame:IsShown() then\n            return true\n        end\n    end\n    return false\nend\n\nlocal function decRound(num, idp)\n    local mult = 10^(idp or 0)\n    return math.floor(num * mult + 0.5) / mult\nend\n\naura_env.kaliels = C_AddOns.IsAddOnLoaded(\"!KalielsTracker\")\naura_env.frame = aura_env.kaliels and _G[\"!KalielsTrackerFrame\"] or ObjectiveTrackerFrame\nif aura_env.config.hideobj then\n    if not aura_env.region.hideobj then\n        aura_env.region.hideobj = true\n        local frame = aura_env.frame\n        hooksecurefunc(frame, \"Show\", function() \n                if IsInInstance() and C_ChallengeMode.IsChallengeModeActive() then frame:Hide() end\n        end)\n    end\nend\n\n\nlocal tooltip = aura_env.config.Tooltip\n\nlocal aura_env = aura_env\nif tooltip ~= 1 and not aura_env.region.tooltipfunc then\n    aura_env.region.tooltipfunc = true\n    aura_env.last = {}\n    local function OnTooltipSetUnit()\n        if select(3, GetInstanceInfo()) == 8 then\n            local GUID = UnitGUID(\"mouseover\")\n            if GUID and MDT then\n                local npcID = select(6, strsplit(\"-\", GUID))\n                local count\n                local max\n                count, max = MDT:GetEnemyForces(tonumber(npcID))\n                if count and max and count ~= 0 and max ~= 0 then\n                    local percent = decRound((count/max)*100, 2)..\"%\"\n                    \n                    local string = (tooltip == 4 and count..\" (\"..percent..\")\") or (tooltip  == 3 and percent) or (tooltip  == 2 and count)\n                    local now = GetTime()\n                    if string and (not aura_env.last[GUID] or now >= aura_env.last[GUID]+0.1) then\n                        aura_env.last[GUID] = now\n                        GameTooltip:AppendText(\" - \"..string)\n                    end\n                end\n            end\n        end\n    end\n    TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Unit, OnTooltipSetUnit)\nend\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["duration"] = "1",
["names"] = {
},
["custom_hide"] = "timed",
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["custom_type"] = "status",
["event"] = "Chat Message",
["unit"] = "player",
["use_absorbMode"] = true,
["spellIds"] = {
},
["events"] = "GOSSIP_SHOW CHALLENGE_MODE_KEYSTONE_RECEPTABLE_OPEN CHALLENGE_MODE_KEYSTONE_SLOTTED CHALLENGE_MODE_START",
["custom"] = "function(e, ...)\n    if e == \"CHALLENGE_MODE_START\" then\n        if aura_env.config[\"hideobj\"] then\n            local frame = aura_env.frame\n            if IsInInstance() and C_ChallengeMode.IsChallengeModeActive() then frame:Hide() end\n        end \n    elseif e == \"STATUS\" and C_ChallengeMode.IsChallengeModeActive() then\n        if aura_env.config[\"hideobj\"] then\n            local frame = aura_env.frame\n            if IsInInstance() and C_ChallengeMode.IsChallengeModeActive() then frame:Hide() end\n        end   \n    elseif e == \"CHALLENGE_MODE_KEYSTONE_SLOTTED\" and aura_env.config.closebags then\n        CloseAllBags()\n    end    \n    \n    if e == \"CHALLENGE_MODE_KEYSTONE_RECEPTABLE_OPEN\" and aura_env.keyslot then\n        local index = select(3, GetInstanceInfo())\n        if index == 8 or index == 23 then\n            for bagID = 0, NUM_BAG_SLOTS do\n                for invID = 1, C_Container.GetContainerNumSlots(bagID) do\n                    local itemID = C_Container.GetContainerItemID(bagID, invID)\n                    if itemID and (aura_env.keyID[itemID]) then \n                        local item = ItemLocation:CreateFromBagAndSlot(bagID, invID)\n                        if item:IsValid() then\n                            local canuse = C_ChallengeMode.CanUseKeystoneInCurrentMap(item)\n                            if canuse then\n                                C_Container.PickupContainerItem(bagID, invID)\n                                C_Timer.After(0.1, function()\n                                        if CursorHasItem() then\n                                            C_ChallengeMode.SlotKeystone()\n                                        end\n                                end)\n                                break\n                            end\n                        end\n                        \n                    end\n                end\n            end\n        end\n    elseif e == \"GOSSIP_SHOW\" then \n        if aura_env.kaliels and aura_env.config[\"hideobj\"] then\n            local frame = aura_env.frame\n            C_Timer.After(0.2, function()\n                    if IsInInstance() and C_ChallengeMode.IsChallengeModeActive() then frame:Hide() end\n            end)\n        end\n        if UnitExists(\"npc\") and (not aura_env.config.gossipctrl or not IsControlKeyDown()) then\n            local GUID = UnitGUID(\"npc\")\n            local id = select(6, strsplit(\"-\", GUID))\n            id = tonumber(id)\n            if aura_env.gossips[id] and aura_env.gossips[id].enabled then\n                local title = C_GossipInfo.GetOptions()\n                local num = aura_env.gossips[id].number\n                if title[num] and title[num].gossipOptionID then\n                    local popupWasShown = aura_env.popup()\n                    C_GossipInfo.SelectOption(title[num].gossipOptionID)\n                    local popupIsShown = aura_env.popup()\n                    if popupIsShown then\n                        if not popupWasShown then\n                            StaticPopup1Button1:Click()\n                        end\n                    end\n                    C_Timer.After(0.3, function()\n                            C_GossipInfo.CloseGossip()\n                    end)\n                end\n            end\n        end\n    end\nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
