["custom"] = "function(event, prefix, msg, channel, sender)    \n    if prefix == \"WA_TRIGGER\" and msg == \"raidtimeinvite\" then\n        \n        \n        local messages = {\n            \"RAID INVITES GOING OUT NOW!\",\n            \"Whisper me: inv  for invite\"\n        }\n        \n        local delay = 0.25  -- Seconds between messages\n        \n        local function sendNextMessage(index)\n            if messages[index] then\n                SendChatMessage(messages[index], \"GUILD\")\n                C_Timer.After(delay, function() sendNextMessage(index + 1) end)\n            end\n        end\n        \n        sendNextMessage(1)\n        \n        \n        return true\n    end\nend",
