["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        local assignments = {\n            \"Front left\",\n            \"Back left\",\n            \"Front right\",\n            \"Back right\",\n        }\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5.8,\n            expirationTime = GetTime() + 5.8,\n            assignment = assignments[math.random(#assignments)],\n            different = math.random(2) == 1,\n            autoHide = true\n        }\n    elseif event == \"LIQUID_GAOL_ASSIGN\" then\n        local assignment, different = ...\n        \n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 5.8,\n            expirationTime = GetTime() + 5.8,\n            assignment = assignment,\n            different = different,\n            autoHide = true\n        }\n        \n        return true\n    end\nend",
