["customText"] = "function()\n    if not aura_env.state then\n        return\n    end\n    \n    if not aura_env.state.name then\n        return\n    end\n    \n    local text = aura_env.state.name\n    \n    if aura_env.state.colorTable then\n        local colorTable = aura_env.state.colorTable\n        local alpha = 255 * (colorTable[4] or 1)\n        local red = 255 * (colorTable[1] or 0)\n        local green = 255 * (colorTable[2] or 0)\n        local blue = 255 * (colorTable[3] or 0)\n        \n        text = string.format(\"\\124c%02x%02x%02x%02x%s\\124r\", alpha, red, green, blue, text)\n    end\n    \n    return text\nend",
