["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 2,\n            expirationTime = GetTime() + 2,\n            autoHide = true\n        }\n    elseif event == \"TRIGGER\" then\n        local _, triggerStates = ...\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        for _, state in pairs(triggerStates) do\n            local unit = state.unit\n            \n            if unit and WeakAuras.CheckRange(unit, 8, \"<=\") then\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = state.duration,\n                    expirationTime = state.expirationTime,\n                    autoHide = true\n                }\n            end\n        end\n        \n        return true\n    end\nend",
