["event"] = "Health",
["names"] = {
},
["customDuration"] = "function()\n    if aura_env.duration then\n        return aura_env.duration, GetTime() + aura_env.duration\n    end\nend",
["custom"] = "function(allstates, event, ...)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        \n        local sub_event = select(2, ...)\n        \n        if sub_event == \"SPELL_CAST_SUCCESS\" then\n            \n            local spell_id = select(12, ...)\n            \n            -- Check if Cloudburst Totem was used\n            if spell_id == 157153 then\n                \n                -- Hide the reminder\n                allstates[\"\"] = {\n                    show = false,\n                    changed = true,\n                }\n                \n                return true\n            end\n        end\n        \n    elseif event == \"USE_CLOUDBURST_TOTEM\" then\n        \n        if IsEncounterInProgress() then\n            \n            -- Get for how many seconds to show the reminder\n            local duration = aura_env.config[\"Duration\"]\n            \n            -- Show the reminder\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = duration,\n                expirationTime = duration + GetTime(),\n                autoHide = true,\n            }\n            \n            return true\n        end\n    end \nend",
["spellIds"] = {
},
["unit"] = "player",
["check"] = "event",
["events"] = "CLEU:SPELL_CAST_SUCCESS, USE_CLOUDBURST_TOTEM",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    duration = {\n        display = \"Duration\",\n        type = \"number\"\n    },\n}",
},
