{
["trigger"] = {
["type"] = "custom",
["custom"] = "function(event, ...)\n    \n    -- Check if Combat mode is active\n    if aura_env.config[\"Mode\"] == 1 then\n        return\n    end\n    \n    -- Check if a watched trigger fired\n    if event == \"TRIGGER\" then\n        \n        local id = select(1, ...)\n        \n        -- Check if the trigger 6 (Boss Mod Timer) fired\n        if id == 6 then\n            \n            local states = select(2, ...)\n            \n            for _, state in pairs(states) do\n                \n                if state.name then\n                    \n                    local spellId\n                    \n                    -- Bandaid for DBM test timers\n                    if state.spellId == \"nil\" then\n                        spellId = state.name\n                    else\n                        spellId = state.spellId\n                    end\n                    \n                    local list                    \n                    \n                    if UnitAffectingCombat(\"player\") == true\n                    or IsEncounterInProgress() == true then\n                        list = aura_env.timers\n                    else\n                        list = aura_env.tests\n                    end\n                    \n                    -- Check if the timer is being already handled\n                    if aura_env.handled[spellId] == nil then\n                        \n                        -- Calculate the exact duration remaining\n                        local duration = state.expirationTime - GetTime()\n                        \n                        if duration >= 0 then\n                            \n                            for key, timer in pairs(list) do\n                                \n                                -- Check if the key is equal to the spellId or is contained in the text of the timer\n                                if tonumber(spellId) == key\n                                or state.name == key\n                                or string.find(state.name, key) then\n                                    \n                                    -- Check if the timer refers to a point in the future\n                                    if duration >= timer then\n                                        \n                                        -- Calculate after how many seconds to fire the scan event\n                                        local delay = duration - timer\n                                        \n                                        if delay >= 0 then\n                                            \n                                            C_Timer.After(delay, function()\n                                                    WeakAuras.ScanEvents(\"USE_CLOUDBURST_TOTEM\")\n                                                end\n                                            )\n                                        end\n                                        \n                                        break\n                                    else\n                                        DebugPrint(\"Warning! The timer for \" .. state.name .. \" can't be higher than \" .. math.floor(duration * 10) / 10 .. \" seconds.\")\n                                    end\n                                end\n                            end\n                            \n                            -- Tell that this timer is being handled\n                            aura_env.handled[spellId] = true\n                            \n                            -- After x seconds, tell that the timer is no longer being handled\n                            C_Timer.After(duration, function()\n                                    aura_env.handled[spellId] = nil\n                                end\n                            )\n                        end\n                    end\n                end\n            end\n            \n            -- Check if the trigger 7 (Boss's Health) fired\n        elseif id == 7 then\n            \n            local states = select(2, ...)\n            \n            if IsInInstance() == true\n            and IsEncounterInProgress() == true then\n                \n                if aura_env.encounter_id\n                and aura_env.percents[aura_env.encounter_id] then\n                    \n                    local encounter = aura_env.percents[aura_env.encounter_id]\n                    \n                    for _, state in pairs(states) do\n                        \n                        local npc_id = tonumber(state.npcId)\n                        \n                        if npc_id and encounter[npc_id] then\n                            \n                            local npc = encounter[npc_id]\n                            \n                            if not aura_env.counters[npc_id] then\n                                aura_env.counters[npc_id] = 1\n                            end\n                            \n                            if not npc[aura_env.counters[npc_id]] then\n                                aura_env.counters[npc_id] = nil\n                                break\n                            end\n                            \n                            if state.percenthealth <= npc[aura_env.counters[npc_id]] then\n                                \n                                WeakAuras.ScanEvents(\"USE_CLOUDBURST_TOTEM\")\n                                aura_env.counters[npc_id] = aura_env.counters[npc_id] + 1\n                            end\n                        end\n                    end\n                end\n            end\n        end\n        \n    elseif event == \"ENCOUNTER_START\" then\n        \n        aura_env.encounter_id = select(1, ...)\n        \n    elseif event == \"ENCOUNTER_END\" then\n        \n        -- Reset the counters for Health thresholds\n        for key, _ in pairs(aura_env.counters) do\n            aura_env.counters[key] = nil\n        end\n        \n        aura_env.encounter_id = nil\n    end\nend",
["custom_type"] = "event",
["debuffType"] = "HELPFUL",
["events"] = "TRIGGER:6:7 ENCOUNTER_START ENCOUNTER_END",
["unit"] = "player",
["custom_hide"] = "timed",
},
["untrigger"] = {
},
},
["disjunctive"] = "custom",
["customTriggerLogic"] = "function(trigger)\n    \n    -- Check if Cloudburst Totem is not active\n    if not (trigger[1] and trigger[2]) then        \n        \n        -- Check if Combat mode is active\n        if aura_env.config[\"Mode\"] == 1 then\n            \n            -- Check if you are in combat and Cloudburst Totem is usable\n            return trigger[3] and trigger[4]\n        else\n            -- Check if a custom timer/event was detected\n            return trigger[5]\n        end\n    end\nend",
