["customText"] = "function()\n    -- Get current Fury amount (Power Type 17 = Fury)\n    local fury = UnitPower(\"player\", 17) or 0\n    \n    -- Find the number of Soul Fragments buff stacks using AuraUtil.FindAuraByName\n    local soulfrag = 0\n    local name, icon, count, debuffType, duration, expirationTime, source, isStealable, nameplateShowPersonal, spellId = \n    AuraUtil.FindAuraByName(\"Soul Fragments\", \"player\", \"HELPFUL\")\n    \n    if spellId == 203981 then -- Check the correct spell ID for Soul Fragments\n        soulfrag = count or 0\n    end\n    \n    return string.format(\"%d / %d\", fury, soulfrag)\nend",
