["adjustedMax"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_time15_format"] = "none",
["displayText_format_split_abbreviate"] = false,
["url"] = "https://wago.io/M+Timer/133",
["actions"] = {
