["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.mapID = aura_env.mapID or 0\naura_env.bossname = aura_env.bossname or {}\naura_env.bosstime = aura_env.bosstime or {}\naura_env.level = 0\naura_env.equal = \"|cFFFFEA00\"\naura_env.ahead = \"|cFF00FF00\"\naura_env.behind = \"|cFFFF0000\"\n\nlocal c = aura_env.config.color\nlocal col = {}\n\nfor i=1, 4 do\n    if i == 4 then \n        col[i] = string.format(\"%x\", c[i] *255)\n    else\n        col[i] = string.format(\"%x\", c[i] *255)\n    end\n    if string.len(col[i]) == 1 then\n        col[i] = \"0\"..col[i]\n    end\nend\n\naura_env.color = \"|c\"..col[4]..col[1]..col[2]..col[3]\n\naura_env.formattime = function(time)\n    local timeMin = math.floor(time / 60)\n    local timeSec = math.floor(time - (timeMin*60))\n    local timeHour = 0\n    if timeMin >= 60 then\n        timeHour = math.floor(time / 3600)\n        timeMin = timeMin - (timeHour * 60)\n    end\n    if timeHour > 0 and timeHour < 10 then\n        timeHour = (\"0%d\"):format(timeHour)\n    end\n    if timeMin < 10 then\n        timeMin = (\"0%d\"):format(timeMin)\n    end\n    if timeSec < 10 then\n        timeSec = (\"0%d\"):format(timeSec)\n    end\n    \n    if timeHour ~= 0 then\n        return (\"%s:%s:%s|r\"):format(timeHour, timeMin, timeSec)\n    else\n        return (\"%s:%s|r\"):format(timeMin, timeSec)\n    end\nend\n\n\naura_env.maptoID = { -- MapChallengeMode = JournalInstance\n    -- Cata\n    [438] = {68, \"Vortex Pinnacle\"},\n    [456] = {65, \"Throne\"},\n    [507] = {71, \"Grim Batol\"},\n    -- MoP\n    [2] = {313, \"Jade Serpent\"},\n    [56] = {302, \"Stromsout\"},\n    [57] = {303, \"Setting Sun\"},\n    [58] = {312, \"Shadow-Pan\"},\n    [59] = {324, \"Niuzao\"},\n    [60] = {321, \"Mogu'shan\"},\n    [76] = {246, \"Scholomance\"},\n    [77] = {311, \"Scarlet Halls\"},\n    [78] = {316, \"Monastery\"},\n    \n    -- WoD\n    [161] = {476, \"Skyreach\"},\n    [163] = {385, \"Slag Mines\"},\n    [164] = {547, \"Auchindoun\"},\n    [165] = {537, \"Shadowmoon\"},\n    [166] = {536, \"Grimrail\"},\n    [167] = {559, \"UBRS\"},\n    [168] = {556, \"Everbloom\"},\n    [169] = {558, \"Iron Docks\"},\n    \n    -- Legion\n    [197] = {716, \"Eye of Azshara\"},\n    [198] = {762, \"Darkheart\"},\n    [199] = {740, \"BRH\"},\n    [200] = {721, \"Halls of Valor\"},\n    [206] = {767, \"Neltharion's Lair\"},\n    [207] = {707, \"Vault\"},\n    [208] = {727, \"Maw of Souls\"},\n    [209] = {726, \"Arcway\"},\n    [210] = {800, \"Court of Stars\"},\n    [227] = {860, \"Kara: Lower\"},\n    [233] = {900, \"Cathedral\"},\n    [234] = {860, \"Kara: Upper\"},\n    [239] = {945, \"Seat\"},\n    \n    -- BfA\n    [244] = {968, \"Atal'Dazar\"},\n    [245] = {1001, \"Freehold\"},\n    [246] = {1002, \"Tol Dagor\"},\n    [247] = {1012, \"Motherlode\"},\n    [248] = {1021, \"Waycrest\"},\n    [249] = {1041, \"King's Rest\"},\n    [250] = {1030, \"Sethraliss\"},\n    [251] = {1022, \"Underrot\"},\n    [252] = {1036, \"Shrine\"},\n    [353] = {1023, \"Boralus\"},\n    [369] = {1178, \"Junkyard\"},\n    [370] = {1178, \"Workshop\"},\n    \n    -- Shadowlands\n    [375] = {1184, \"Mists\"},\n    [376] = {1182, \"Necrotic Wake\"},\n    [377] = {1188, \"Other Side\"},\n    [378] = {1185, \"Halls\"},\n    [379] = {1183, \"Plaguefall\"},\n    [380] = {1189, \"Sanguine\"},\n    [381] = {1186, \"Spires\"},\n    [382] = {1187, \"Theater\"},\n    [391] = {1194, \"Streets\"},\n    [392] = {1194, \"Gambit\"},\n    \n    -- Dragonflight\n    \n    \n    [399] = {1202, \"Ruby Pools\"},\n    [400] = {1198, \"Nokhud\"},\n    [401] = {1203, \"Azure Vault\"},\n    [402] = {1201, \"Academy\"},\n    [403] = {1197, \"Uldaman\"},\n    [404] = {1199, \"Neltharus\"},\n    [405] = {1196, \"Brackenhide\"},\n    [406] = {1204, \"Halls\"},\n    [463] = {1209, \"DotI: Lower\"},\n    [464] = {1209, \"DotI: Upper\"},\n    \n    -- The War Within\n    \n    [499] = {1267, \"Sacred Flame\"},\n    [500] = {1268, \"The Rookery\"},\n    [501] = {1269, \"Stonevault\"},\n    [502] = {1274, \"City of Threads\"},\n    [503] = {1271, \"Ara-Kara\"},\n    [504] = {1210, \"Darkflame Cleft\"},\n    [505] = {1270, \"Dawnbreaker\"},\n    [506] = {1272, \"Cinderbrew Maedery\"},\n    \n    \n}\n\n\n\naura_env.setbossnames = function()\n    local mapID = C_Map.GetBestMapForUnit(\"player\")\n    local instanceID = (mapID and EJ_GetInstanceForMap(mapID)) or 0 -- find instanceid from encounter journal\n    local cmapID = C_ChallengeMode.GetActiveChallengeMapID()\n    if instanceID == 0 or instanceID == nil then -- if it didn't work, use hardcoded cmapid table instead\n        if cmapID and aura_env.maptoID[cmapID] then\n            instanceID = aura_env.maptoID[cmapID][1]\n        end\n    end\n    if instanceID and instanceID ~= 0 then\n        EJ_SelectInstance(instanceID)\n        aura_env.bossname = {}\n        aura_env.bosstime = {}\n        for i=1, 20 do\n            local name = EJ_GetEncounterInfoByIndex(i, instanceID)\n            if name then\n                aura_env.bossname[i] = name\n            elseif aura_env.config.fixbosses and i == 1 and not aura_env.opened then\n                C_AddOns.LoadAddOn(\"Blizzard_EncounterJournal\")\n                EncounterJournal_OpenJournal(8, instanceID) \n                aura_env.opened = true\n                HideUIPanel(EncounterJournal)\n                local name = EJ_GetEncounterInfoByIndex(i, instanceID)\n                if name then\n                    aura_env.bossname[i] = name\n                end\n            end            \n        end\n    end\nend\nDebugPrint(aura_env.saved)",
["do_custom"] = true,
