["url"] = "https://wago.io/LiquidUndermine/4",
["icon"] = false,
["triggers"] = {
{
["trigger"] = {
["useMatch_count"] = true,
["combinePerUnit"] = false,
["names"] = {
},
["subeventPrefix"] = "SPELL",
["match_count"] = "0",
["custom_type"] = "stateupdate",
["ignoreInvisible"] = false,
