["custom_type"] = "event",
["duration"] = "5",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["spellIds"] = {
},
["custom"] = "function(event, ...)\n    local _, subEvent, _, _, _, _, _, _, _, _, _, spellID = ...\n    \n    if subEvent == \"SPELL_CAST_SUCCESS\" and spellID == 473531 then -- Empty Tank\n        local auraInfo = C_UnitAuras.GetPlayerAuraBySpellID(473507) -- Soaked in Oil\n        local expirationTime = auraInfo and auraInfo.expirationTime or 0\n        \n        return expirationTime > GetTime() + 5\n    end\nend",
