{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    if event == \"OPTIONS\" then\n        allstates[1] = {\n            show = true,\n            changed = true,\n            unit = \"player\",\n            assignment = math.random(4)\n        }\n    elseif event == \"LIQUID_FOOT_BLASTER_ASSIGNMENT\" then\n        local set, assignments, isMythic = ...\n        \n        for _, state in pairs(allstates) do\n            state.show = false\n            state.changed = true\n        end\n        \n        for i, entry in ipairs(assignments) do\n            if entry.GUID then\n                allstates[i] = {\n                    show = true,\n                    changed = true,\n                    unit = UnitTokenFromGUID(entry.GUID),\n                    assignment = entry.order,\n                }\n            end\n        end\n        \n        return true\n    end\nend",
