["custom"] = "aura_env.loaded = C_AddOns.IsAddOnLoaded(\"CauseseDB\")\nif aura_env.loaded then\n    aura_env.timer = {}\n    aura_env.scanned = {}\n    \n    --category is used to color the bars in the conditions, apply countdown only to certain categories etc etc\n    --role can be ALL/TANK/DAMAGER/HEALER (to only show bars to that role. this requires being in a dungeon group, otherwise you have no role)\n    \n    --{[\"npcID\"] = {[spellID] = {\"event\", \"category\", role, \"name\", \"initialTimer\", \"recastTimer\", \"delay\" (optional, recastTimer)}}\n    aura_env.timers = {\n        --timers moved to CauseseDB AddOn. Timers specified here will be prefered over CauseseDB\n        \n        --[\"214697\"] = {[463206] = {\"SPELL_CAST_START\", 1, \"ALL\", \"Knock Inc\", 8.1, 18.1}}, --Example\n    }\n    \n    \n    --default categories:\n    --0 = AoE etc + countdown sound for non-ccable mobs\n    --1 = AoE without countdown for non-ccable mobs\n    --2 = Important\n    --3 = CCable only\n    --4 = tankbuster\n    --5 = Spawns Pools / Forces you to move\n    --6 = Interruptible\n    --7 = non interruptible shouts that buff enemies or debuff friendlies\n    \n    --you can make up your own numbers\nend",
