["[GLOBAL-TRASH] Targeted (cast on you)"] = {
["iconSource"] = -1,
["wagoID"] = "tcIVwLsy9",
["authorOptions"] = {
},
["adjustedMax"] = "",
["customText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["actions"] = {
["start"] = {
["do_custom"] = false,
["sound"] = " custom",
["custom"] = "\n\n",
["do_sound"] = false,
},
["init"] = {
["custom"] = "aura_env.loaded = C_AddOns.IsAddOnLoaded(\"CauseseDB\")\nif aura_env.loaded then\n    aura_env.allowlist = {\n        --spellIDs moved to CauseseDB\n        --[123456] = {\"Targeted\", \"Targeted.ogg\"}, --Example\n    }\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["auranames"] = {
"320168",
},
["unit"] = "player",
["debuffType"] = "HARMFUL",
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_type"] = "stateupdate",
["useName"] = true,
["event"] = "Health",
["useExactSpellId"] = false,
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, unit, _, spellID)\n    if aura_env.loaded then\n        if (event == \"UNIT_TARGET\" or event == \"CAUSESE_DELAYED_SPELLCAST\")\n        and UnitExists(unit)\n        and UnitIsUnit(unit..\"target\", \"player\")\n        then\n            local _,_,icon,_,expirationTime,_,_,_,spellId = UnitCastingInfo(unit)\n            if spellId then\n                local spell = aura_env.allowlist[spellId] or CauseseDB.targeted[spellId]\n                if spell then\n                    local guid = UnitGUID(unit)\n                    if guid and not allstates[guid] then\n                        local name, sound = unpack(spell)\n                        PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Causese\\\\sound\\\\\"..sound, \"MASTER\")\n                        allstates[guid] = {\n                            show = true,\n                            changed =  true,\n                            progressType = \"timed\", \n                            duration = expirationTime / 1000 - GetTime(),\n                            expirationTime = expirationTime / 1000,\n                            name = name,\n                            icon = icon,\n                            autoHide = true,\n                            spellID = spellId\n                        }\n                        return true\n                    end\n                end\n            end\n            \n        elseif event == \"UNIT_SPELLCAST_START\" and (aura_env.allowlist[spellID] or CauseseDB.targeted[spellID]) then\n            C_Timer.After(0.15, function() WeakAuras.ScanEvents(\"CAUSESE_DELAYED_SPELLCAST\", unit) end)\n            \n        elseif (\n            event == \"UNIT_SPELLCAST_SUCCEEDED\"\n            or event == \"UNIT_SPELLCAST_STOP\"\n            or event == \"UNIT_SPELLCAST_FAILED\"\n            or event == \"UNIT_SPELLCAST_INTERRUPTED\"\n        )    \n        and UnitExists(unit)\n        then\n            local guid = UnitGUID(unit)\n            if guid then\n                local state = allstates[guid]\n                if state then\n                    state.show = false\n                    state.changed = true\n                    return true\n                end\n            end\n        end\n    end\nend",
