["displayText_format_p_time_dynamic_threshold"] = 60,
["customText"] = "function(_, _, progress, _, name, icon)\n    if not aura_env.state then return false end \n    local s = \"\"\n    if WeakAuras.IsOptionsOpen() then\n        for i = 1, 5, 1 do \n            if aura_env.config.display[\"Option\"..i] == 1 then\n                -- None\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n            if aura_env.config.display[\"Option\"..i] == 2 then\n                -- Icon\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..\"|Tinterface/icons/Spell_magic_managain.blp:16|t\"..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n            if aura_env.config.display[\"Option\"..i] == 3 then\n                -- Caster\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..WA_ClassColorName(\"player\")..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n            if aura_env.config.display[\"Option\"..i] == 4 then\n                -- Spell Name\n                local r = aura_env.config.display.spellNameColor[1]\n                local g = aura_env.config.display.spellNameColor[2]\n                local b = aura_env.config.display.spellNameColor[3]\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..(\"|c%s%s|r\"):format((\"ff%.2x%.2x%.2x\"):format(r*255, g*255, b*255), \"Rabbit\")..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n            if aura_env.config.display[\"Option\"..i] == 5 then\n                -- Target\n                local _, class = UnitClass(\"player\")\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..(\"|c%s%s|r\"):format(RAID_CLASS_COLORS[class].colorStr, UnitName(\"player\"):reverse():lower():gsub(\"^%l\", string.upper))..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n            if aura_env.config.display[\"Option\"..i] == 6 then\n                -- Progress\n                s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..progress..(aura_env.config.display[\"afterOption\"..i] or \"\")\n            end\n        end\n        return s\n    end\n    for i = 1, 5, 1 do \n        if aura_env.config.display[\"Option\"..i] == 1 then\n            -- None\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..\"\"..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        elseif aura_env.config.display[\"Option\"..i] == 2 then\n            -- Icon\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..icon..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        elseif aura_env.config.display[\"Option\"..i] == 3 then\n            -- Caster\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..aura_env.state.sourceName..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        elseif aura_env.config.display[\"Option\"..i] == 4 then\n            -- Spell Name\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..aura_env.state.name..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        elseif aura_env.config.display[\"Option\"..i] == 5 and aura_env.spells[aura_env.state.spellID].target then\n            -- Target\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..aura_env.state.destName..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        elseif aura_env.config.display[\"Option\"..i] == 6 then\n            s = s..(aura_env.config.display[\"beforeOption\"..i] or \"\")..progress..(aura_env.config.display[\"afterOption\"..i] or \"\")\n        end\n    end\n    return s\nend",
