["custom"] = "aura_env.spells = {}\n\nlocal spellNameColorRGB = aura_env.config.display.spellNameColor\nlocal r, g, b = spellNameColorRGB[1], spellNameColorRGB[2], spellNameColorRGB[3]\naura_env.spellNameColorHEX = (\"ff%.2x%.2x%.2x\"):format(r*255, g*255, b*255)\n\n-- Grabbing all enabled spells. \nfor _,t in pairs(aura_env.config.spells) do \n    if t.enable then \n        aura_env.spells[t.id] = {\n            [\"name\"] = t.name,\n            [\"duration\"] = t.duration,\n            [\"target\"] = t.target,\n            [\"channeled\"] = t.channeled,\n        }\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(allstates, event, unitID, subEvent, channelSpellID, sourceGUID, sourceName, sourceFlags, _, destGUID, destName, destFlags, _, spellID)\n    if type(allstates) ~= \"table\" then\n        return\n    end \n    if spellID == 33891 and allstates[sourceName..spellID] then\n        return\n    end\n    if spellID == 31884 and UnitGroupRolesAssigned(sourceName) ~= \"HEALER\" then\n        return\n    end\n    if sourceName and aura_env.spells[spellID] then \n        sourceName = Ambiguate(sourceName, \"short\")\n        if destName then destName = Ambiguate(destName, \"short\") end\n    end\n    if event == \"UNIT_SPELLCAST_CHANNEL_STOP\" and aura_env.spells[channelSpellID] then \n        local name, realm\n        if unitID then \n            name, realm = UnitName(unitID)\n        end\n        if allstates[name..channelSpellID] then \n            allstates[name..channelSpellID].changed = true\n            allstates[name..channelSpellID].show = false\n        end\n    end\n    if subEvent == \"SPELL_CAST_SUCCESS\" and aura_env.spells[spellID] then\n        local state = {}\n        allstates[sourceName..spellID] = state\n        local _, classSource = UnitClass(sourceName)\n        state.sourceName = classSource and (\"|c%s%s|r\"):format(RAID_CLASS_COLORS[classSource].colorStr, sourceName) or sourceName\n        if destName then \n            local _, classDestination = UnitClass(destName)\n            state.destName = classDestination and (\"|c%s%s|r\"):format(RAID_CLASS_COLORS[classDestination].colorStr, destName) or destName\n        end\n        state.show = true\n        state.changed = true\n        state.name = (\"|c%s%s|r\"):format(aura_env.spellNameColorHEX, C_Spell.GetSpellName(spellID))\n        state.progressType = 'timed'\n        state.expirationTime = GetTime() + aura_env.spells[spellID].duration\n        state.duration = aura_env.spells[spellID].duration\n        state.autoHide = true\n        state.resort = true\n        state.icon = C_Spell.GetSpellInfo(spellID)[\"iconID\"]\n        state.spellID = spellID\n        if aura_env.config.debug then ViragDevTool_AddData(allstates[sourceName..spellID], \"allstates[\"..sourceName..spellID..\"]\") end\n    end\n    return true\nend",
