["spellIds"] = {
},
["custom"] = "function()\n    local specID = GetSpecialization()\n    if not specID then return \"Unknown Spec\" end\n    \n    local specInfo = GetSpecializationInfo(specID)\n    if not specInfo then return \"Unknown Spec\" end\n    \n    local specIDNum = select(1, GetSpecializationInfo(specID))\n    if not specIDNum then return \"Unknown Spec\" end\n    \n    local configID = C_ClassTalents.GetLastSelectedSavedConfigID(specIDNum)\n    if not configID then return \"No Loadout\" end\n    \n    local configInfo = C_Traits.GetConfigInfo(configID)\n    if not configInfo or not configInfo.name then return \"Unnamed Loadout\" end\n    \n    local inInstance, instanceType = IsInInstance()\n    if inInstance then\n        local _,instanceType,_,_,_,_,_,_,_,_ = GetInstanceInfo()\n        \n        if instanceType == \"scenario\" then\n            if (string.lower(aura_env.config.wrong_spec_dummy_delves) ~= string.lower(configInfo.name)) then\n                return true\n            end\n        elseif instanceType == \"party\" then\n            if (string.lower(aura_env.config.wrong_spec_dummy_mplus) ~= string.lower(configInfo.name)) then\n                return true\n            end\n        elseif instanceType == \"raid\" then\n            if (string.lower(aura_env.config.wrong_spec_dummy_raids) ~= string.lower(configInfo.name)) then\n                return true\n            end\n        elseif instanceType == \"pvp\" then\n            if (string.lower(aura_env.config.wrong_spec_dummy_pvp) ~= string.lower(configInfo.name)) then\n                return true\n            end\n        end\n    else\n        if (string.lower(aura_env.config.wrong_spec_dummy_openworld) ~= string.lower(configInfo.name)) then\n            return true\n        else\n            return false\n        end\n    end\nend",
